import React, { useState } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import InputField from '../../../components/ui/InputField/InputField';
import Button from '../../../components/ui/Button/Button';
import api from '../../../api/api';

const CreateAdminPage = () => {
  // Estado para controlar os valores do formulário
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
  });

  // Função para atualizar o estado quando o utilizador digita
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({
      ...prevState,
      [name]: value,
    }));
  };

  // Função para lidar com a submissão do formulário
  const handleSubmit = async (e) => {
    e.preventDefault(); // Impede o recarregamento da página
    try {
      // Faz um pedido POST para /api/admins com os dados do formulário
      const response = await api.post('/admins', formData);
      alert(`Admin "${response.data.name}" criado com sucesso!`);
      // Limpa o formulário após o sucesso
      setFormData({ name: '', email: '', password: '' });
    } catch (error) {
      console.error("Erro ao criar administrador:", error);
      alert("Ocorreu um erro. Verifique a consola.");
    }
  };

  return (
    <ContentWrapper title="Cadastrar Admin Nível 1">
      <form onSubmit={handleSubmit}>
        <InputField 
          label="Nome Completo" 
          name="name" 
          placeholder="Nome do administrador"
          value={formData.name}
          onChange={handleChange}
        />
        <InputField 
          label="Email" 
          type="email" 
          name="email" 
          placeholder="email@exemplo.com"
          value={formData.email}
          onChange={handleChange}
        />
        <InputField 
          label="Senha Provisória" 
          type="password" 
          name="password"
          value={formData.password}
          onChange={handleChange}
        />
        <Button type="submit">Cadastrar Administrador</Button>
      </form>
    </ContentWrapper>
  );
};

export default CreateAdminPage;
